e,=json.loads((p/'source-manifest.json').read_text())['rows'];n='Sign17ParamDecoder';q=p/'src/DiophantineConsistency'/(n+'.lean');s=q.read_text();assert e['module']=='DiophantineConsistency.'+n and e['imports']==['DiophantineConsistency.Sign17KByteBinding'] and sha(q)==sha(repo/e['source'])==e['source_sha256']=='24ed4e8ce86227e2fbd4fbb10af950796de462d95689d4e47c27e0effe400099' and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==e['imports'] and not re.search(r'(?m)^\s*(axiom|opaque|partial)\b|\b(sorry|admit|native_decide)\b',s)
old=(root/'Lean/DiophantineConsistency/DecimalMachine215.lean').read_text()
for z in ('seed % 2 ^ 636','seed / 2 ^ 636','digit 2 mask j','sigma j + discovery j','(sigma j + 2) ^ (1 - discovery j)','prefixProduct j * radix j','digit 2 mask (430 + q)','tally q + mark q','digit 16 (payload / prefixProduct 430) (tally q)','sigma (j + 1) : ℤ','payload / prefixProduct j % radix j','(rawTarget j % 216).toNat','2 * (j % 2) + 1'):assert z in old
for z in ('A % 2 ^ 636','A / 2 ^ 636','digit 2 (maskAt A) j','sigmaAt A j + discoveryAt A j','(sigmaAt A j + 2) ^ (1 - discoveryAt A j)','prefixAt A j * radixAt A j','digit 2 (maskAt A) (430 + q)','tallyAt A q + markAt A q','digit 16 (payloadAt A / prefixAt A 430) (tallyAt A q)','sigmaAt A (j + 1) : ℤ','payloadAt A / prefixAt A j % radixAt A j','(rawTargetAt A j % 216).toNat','2 * (j % 2) + 1','theorem action_seed (j : ℕ) : actionAt DecimalMachine215.seed j = DecimalMachine215.action j'):assert z in s
subprocess.run([sys.executable,'-I','-S','-B',str(root/'reviews/nine-sharing-sign17-k-byte-binding-retry-terminal-independent/check.py')],capture_output=True,check=True,timeout=180)
prior=json.loads((root/'research/nine-sharing-sign17-k-byte-binding-retry-check/attempt01/state.json').read_text());assert prior['status']=='PASS';obj=Path('/tmp/nine-sharing-sign17-k-byte-binding-retry-20261110/lib/DiophantineConsistency/Sign17KByteBinding.olean');assert sha(obj)==prior['rows'][0]['object_sha256']
r=(p/'run.py').read_text();assert "need('Init' in deps" in r and "env['LEAN_NUM_THREADS']='1'" in r and "str(candidates[0])==rec['path']" in r and "rec['realpath']==provider_init['realpath'] and rec['sha256']==provider_init['sha256']" in r and "'-M3600'" in r and "'-j1'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r
x=subprocess.run([sys.executable,'-I','-S','-B',str(p/'run.py'),'--preflight'],capture_output=True,text=True,check=True,timeout=180);assert not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','scope':'parameterized decoder specialization to existing in-Lean seed only; no SeedLines, cache, PDF or external file theorem'},indent=2))
